### 2. 实体模板 (Entity)

用于游戏实体，如 Player、Enemy 等。

```gdscript
## {{CLASS_DESCRIPTION}}
##
## @author AI Generated
## @version {{VERSION}}
class_name {{CLASS_NAME}}
extends {{BASE_CLASS}}

# region 信号
signal died
signal health_changed(old_value: int, new_value: int)
{{ADDITIONAL_SIGNALS}}
# endregion

# region 导出变量
@export_group("Stats")
@export var max_health: int = 100
@export var move_speed: float = 200.0
{{ADDITIONAL_EXPORTS}}
# endregion

# region 状态变量
var current_health: int:
    set(value):
        var old = current_health
        current_health = clampi(value, 0, max_health)
        health_changed.emit(old, current_health)
        if current_health <= 0:
            _die()
    get:
        return current_health

var is_alive: bool:
    get: return current_health > 0
{{ADDITIONAL_STATE}}
# endregion

# region 组件引用
{{COMPONENT_REFS}}
# endregion

# region 生命周期
func _ready() -> void:
    _setup_components()
    _initialize()

func _physics_process(delta: float) -> void:
    if not is_alive:
        return
    {{PHYSICS_CONTENT}}
# endregion

# region 公共方法
func take_damage(amount: int, source: Node = null) -> void:
    if not is_alive:
        return
    current_health -= amount

func heal(amount: int) -> void:
    if not is_alive:
        return
    current_health += amount
{{ADDITIONAL_PUBLIC}}
# endregion

# region 私有方法
func _setup_components() -> void:
    {{SETUP_COMPONENTS}}

func _initialize() -> void:
    current_health = max_health
    {{INIT_CONTENT}}

func _die() -> void:
    died.emit()
    {{DIE_CONTENT}}
{{ADDITIONAL_PRIVATE}}
# endregion
```

